.syntax unified
.arm

.section .text.start
.global start

.equ R_ARM_RELATIVE, 23

start:
    adr r9, _image_start       @ PIC base register

    /*
     * The payload is linked as a PIE but is executed directly from a raw
     * binary at DA_ADDR.  Apply the R_ARM_RELATIVE relocations generated by
     * the linker before touching any C global that may use the GOT.
     */
    adr r0, _runtime_info_start
    ldr r1, [r0, #0]
    add r1, r1, r9             @ runtime _rel_dyn_start
    ldr r2, [r0, #4]
    add r2, r2, r9             @ runtime _rel_dyn_end
    ldr r5, [r0, #8]
    add r5, r5, r9             @ runtime _stack_top

1:
    cmp r1, r2
    bhs 3f

    ldr r3, [r1, #4]           @ r_info
    and r3, r3, #0xff          @ ELF32 relocation type
    cmp r3, #R_ARM_RELATIVE
    bne 2f

    ldr r0, [r1]               @ r_offset
    add r0, r0, r9             @ runtime relocation target
    ldr r4, [r0]
    add r4, r4, r9             @ add runtime load delta
    str r4, [r0]

2:
    add r1, r1, #8
    b 1b

3:
    mov sp, r5
    mov r0, r9                 @ main(uint32_t runtime_base)
    blx payload_bootstrap
    b   .
